def _parse(version):
    """Return a sortable key for a SemVer string (build metadata ignored)."""
    without_build = version.split("+", 1)[0]

    if "-" in without_build:
        core, prerelease = without_build.split("-", 1)
        prerelease_ids = prerelease.split(".")
    else:
